import unittest
from pricing import apply_discount


class HiddenPricingTest(unittest.TestCase):
    def test_quarter_off(self):
        self.assertEqual(apply_discount(200, 25), 150.0)

    def test_rounding(self):
        self.assertEqual(apply_discount(19.99, 15), 16.99)

    def test_full_discount(self):
        self.assertEqual(apply_discount(80, 100), 0.0)

    def test_invalid_percent(self):
        with self.assertRaises(ValueError):
            apply_discount(10, 101)
        with self.assertRaises(ValueError):
            apply_discount(10, -1)


if __name__ == "__main__":
    unittest.main()

